INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-221','MAP','reading','mcq',3,'When the town planted trees along Maple Street, many residents complained about the cost. Ten years later, the shade lowered summer temperatures by several degrees, and neighbours began gathering under the branches each evening. The mayor admitted that the trees had paid for themselves in ways no budget could measure.','What is the mayor''s attitude toward the trees by the end of the passage?',NULL,'["Regretful","Appreciative","Confused","Angry"]',1,'He admits they paid for themselves.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-222','MAP','reading','mcq',4,'When the town planted trees along Maple Street, many residents complained about the cost. Ten years later, the shade lowered summer temperatures by several degrees, and neighbours began gathering under the branches each evening. The mayor admitted that the trees had paid for themselves in ways no budget could measure.','Which sentence best states a theme of the passage?',NULL,'["Costs should never be questioned.","Some investments bring benefits that are hard to measure.","Trees grow slowly.","Neighbours dislike change."]',1,'Benefits beyond budget.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-223','MAP','reading','mcq',2,'When the town planted trees along Maple Street, many residents complained about the cost. Ten years later, the shade lowered summer temperatures by several degrees, and neighbours began gathering under the branches each evening. The mayor admitted that the trees had paid for themselves in ways no budget could measure.','According to the passage, what happened ten years later?',NULL,'["The trees were cut down","Summers became cooler and neighbours gathered","The street was closed","The mayor resigned"]',1,'Stated directly.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-224','MAP','reading','mcq',4,'Scientists studying coral reefs have noticed that reefs near busy harbours often recover more slowly after storms. The researchers suspect that pollution weakens the coral, but they caution that more data is needed before the cause can be confirmed.','Which word best describes the researchers'' conclusion?',NULL,'["Certain","Tentative","Careless","Hostile"]',1,'"Suspect" and "more data is needed" signal caution.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-225','MAP','reading','mcq',5,'Scientists studying coral reefs have noticed that reefs near busy harbours often recover more slowly after storms. The researchers suspect that pollution weakens the coral, but they caution that more data is needed before the cause can be confirmed.','What does "caution" mean as used in the passage?',NULL,'["to hurry","to warn","to celebrate","to ignore"]',1,'To caution = to warn.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-226','MAP','reading','mcq',3,'Scientists studying coral reefs have noticed that reefs near busy harbours often recover more slowly after storms. The researchers suspect that pollution weakens the coral, but they caution that more data is needed before the cause can be confirmed.','What is the passage mainly about?',NULL,'["How storms form","A possible link between harbours and slow reef recovery","Why harbours are busy","How to build harbours"]',1,'Main idea.',1,0);
