INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-228','MAP','reading','mcq',3,NULL,'Which word is closest in meaning to "abundant"?',NULL,'["plentiful","empty","fragile","ordinary"]',0,'Abundant = plentiful.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-229','MAP','reading','mcq',4,NULL,'"The wind whispered through the trees." This sentence is an example of',NULL,'["simile","personification","exaggeration","rhyme"]',1,'The wind is given a human action.',1,0);
